  providers: [
    provideBrnDialogDefaultOptions({
      ...BRN_ALERT_DIALOG_DEFAULT_OPTIONS,
      hasBackdrop: true,
      closeOnOutsidePointerEvents: false,
      restoreFocus: true,
      autoFocus: 'first-tabbable',
