import { NgTemplateOutlet } from '@angular/common';
import {
  booleanAttribute,
  Component,
  computed,
  contentChild,
  Directive,
  forwardRef,
  inject,
  input,
  model,
  output,
  signal,
  TemplateRef,
} from '@angular/core';
import { type ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';
import type { FormValueControl } from '@angular/forms/signals';
import { Listbox, Option } from '@angular/aria/listbox';

import type { WiListboxCompareWith, WiListboxItemContext, WiListboxSize } from './wi-listbox.types';

const LIST_BASE_CLASSES = [
  'wi-listbox__list',
  'flex',
  'w-full',
  'min-w-0',
  'max-h-60',
  'flex-col',
  'overflow-x-hidden',
  'overflow-y-auto',
  'rounded-control',
  'border',
  'border-outline',
  'bg-surface',
  'text-on-surface',
  'outline-none',
  'focus-visible:ring-2',
  'focus-visible:ring-ring',
  'focus-visible:ring-offset-2',
  'focus-visible:ring-offset-background',
  'aria-disabled:pointer-events-none',
  'aria-disabled:opacity-50',
  'aria-invalid:border-error',
  'aria-invalid:focus-visible:ring-error',
].join(' ');

const LIST_SIZE_CLASSES: Record<WiListboxSize, string> = {
  sm: 'p-0.5 text-sm',
  md: 'p-1 text-sm',
  lg: 'p-1.5 text-base',
};

const OPTION_BASE_CLASSES = [
  'wi-listbox__option',
  'group',
  'relative',
  'flex',
  'w-full',
  'min-w-0',
  'cursor-default',
  'items-center',
  'gap-2',
  'rounded-control',
  'outline-none',
  'select-none',
  'hover:bg-surface-variant',
  'data-[active=true]:bg-surface-variant',
  'aria-selected:bg-primary-container',
  'aria-selected:text-on-primary-container',
  'aria-disabled:pointer-events-none',
  'aria-disabled:opacity-50',
].join(' ');

const OPTION_SIZE_CLASSES: Record<WiListboxSize, string> = {
  sm: 'px-2 py-1 text-sm',
  md: 'px-2 py-1.5 text-sm',
  lg: 'px-3 py-2 text-base',
};

const OPTION_CHECK_CLASSES = [
  'wi-listbox__check',
  'size-4',
  'shrink-0',
  'opacity-0',
  'group-aria-selected:opacity-100',
].join(' ');

let nextListboxId = 0;

/**
 * Marca un `ng-template` como plantilla de ítem del listbox.
 *
 * @example
 * ```html
 * <ng-template wiListboxItem let-option let-value="value" let-selected="selected">...</ng-template>
 * ```
 */
@Directive({
  selector: 'ng-template[wiListboxItem]',
})
export class WiListboxItemDirective {
  readonly template = inject(TemplateRef<WiListboxItemContext>);
}

/**
 * Listbox del design system (`wi-listbox`).
 *
 * - Lista siempre visible (sin overlay).
 * - Single o multi vía `multiple` (estático; no cambiar en runtime).
 * - Sin filtro ni virtual scroll.
 * - `FormValueControl` + `ControlValueAccessor`.
 * - Label / hint / error quedan fuera (composición `wi-field` prevista).
 */
@Component({
  selector: 'wi-listbox',
  imports: [NgTemplateOutlet, Listbox, Option],
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => WiListboxComponent),
      multi: true,
    },
  ],
  host: {
    class: 'wi-listbox block w-full min-w-0',
  },
  template: `
    <ul
      ngListbox
      [id]="resolvedId()"
      [class]="listClasses()"
      [value]="ariaValues()"
      [multi]="multiple()"
      [disabled]="isDisabled()"
      selectionMode="explicit"
      orientation="vertical"
      [attr.aria-label]="ariaLabel()"
      [attr.aria-labelledby]="ariaLabelledBy()"
      [attr.aria-describedby]="ariaDescribedBy()"
      [attr.aria-required]="required() || null"
      [attr.aria-invalid]="invalid() || null"
      [attr.name]="name() || null"
      (valueChange)="onAriaValueChange($event)"
      (focusout)="onFocusOut($event)"
    >
      @for (option of options(); track trackOption($index, option)) {
        <li
          ngOption
          [class]="optionClasses()"
          [value]="resolveOptionValue(option)"
          [label]="resolveOptionLabel(option)"
        >
          <span class="min-w-0 flex-1 truncate">
            @if (resolvedItemTemplate(); as itemTpl) {
              <ng-container *ngTemplateOutlet="itemTpl; context: itemContext(option)" />
            } @else {
              {{ resolveOptionLabel(option) }}
            }
          </span>
          <svg
            [class]="optionCheckClasses"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width="1.5"
            aria-hidden="true"
          >
            <path stroke-linecap="round" stroke-linejoin="round" d="m4.5 12.75 6 6 9-13.5" />
          </svg>
        </li>
      } @empty {
        <li class="wi-listbox__empty px-2 py-1.5 text-on-surface-variant" aria-hidden="true">
          {{ emptyText() }}
        </li>
      }
    </ul>
  `,
})
export class WiListboxComponent implements ControlValueAccessor, FormValueControl<unknown> {
  /** Valor del control. Single: `T | null`. Multi: `T[]`. */
  readonly value = model<unknown>(null);

  readonly multiple = input(false, { transform: booleanAttribute });
  readonly options = input<readonly unknown[]>([]);
  readonly optionLabel = input<string | undefined>(undefined);
  readonly optionValue = input<string | undefined>(undefined);
  readonly compareWith = input<WiListboxCompareWith>(Object.is);

  readonly size = input<WiListboxSize>('md');
  readonly emptyText = input('');

  readonly id = input<string | undefined>(undefined);
  readonly name = input('');
  readonly ariaLabel = input<string | null>(null);
  readonly ariaLabelledBy = input<string | null>(null);
  readonly ariaDescribedBy = input<string | null>(null);

  readonly disabled = input(false, { transform: booleanAttribute });
  readonly invalid = input(false, { transform: booleanAttribute });
  readonly required = input(false, { transform: booleanAttribute });

  /** Template de ítem por input (alternativa a `ng-template wiListboxItem`). */
  readonly itemTemplate = input<TemplateRef<WiListboxItemContext> | undefined>(undefined);

  /** Emite en blur / cambio de valor (Signal Forms: touched). */
  readonly touch = output<void>();

  private readonly itemTemplateDir = contentChild(WiListboxItemDirective);

  private readonly generatedId = `wi-listbox-${++nextListboxId}`;
  private readonly cvaDisabled = signal(false);

  private onChange: (value: unknown) => void = () => undefined;
  private onTouched: () => void = () => undefined;

  protected readonly optionCheckClasses = OPTION_CHECK_CLASSES;

  protected readonly resolvedId = computed(() => this.id() ?? this.generatedId);

  protected readonly isDisabled = computed(() => this.disabled() || this.cvaDisabled());

  protected readonly listClasses = computed(() =>
    [LIST_BASE_CLASSES, LIST_SIZE_CLASSES[this.size()]].join(' '),
  );

  protected readonly optionClasses = computed(() =>
    [OPTION_BASE_CLASSES, OPTION_SIZE_CLASSES[this.size()]].join(' '),
  );

  protected readonly resolvedItemTemplate = computed(
    () => this.itemTemplate() ?? this.itemTemplateDir()?.template,
  );

  /**
   * Valores para `@angular/aria` Listbox (siempre `V[]`).
   * Single: 0–1 elementos; multi: el array del form.
   */
  protected readonly ariaValues = computed((): unknown[] => {
    const current = this.value();
    if (this.multiple()) {
      return Array.isArray(current) ? [...current] : [];
    }
    if (current === null || current === undefined || current === '') {
      return [];
    }
    return [current];
  });

  writeValue(value: unknown): void {
    if (this.multiple()) {
      this.value.set(Array.isArray(value) ? value : []);
      return;
    }
    this.value.set(value ?? null);
  }

  registerOnChange(fn: (value: unknown) => void): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this.cvaDisabled.set(isDisabled);
  }

  protected onAriaValueChange(next: unknown[]): void {
    if (this.multiple()) {
      const normalized = Array.isArray(next) ? next : [];
      this.value.set(normalized);
      this.onChange(normalized);
    } else {
      const single = next.length > 0 ? next[0] : null;
      this.value.set(single);
      this.onChange(single);
    }
    this.markTouched();
  }

  protected onFocusOut(event: FocusEvent): void {
    const host = event.currentTarget as HTMLElement | null;
    const related = event.relatedTarget as Node | null;
    if (host && related && host.contains(related)) {
      return;
    }
    this.markTouched();
  }

  protected resolveOptionValue(option: unknown): unknown {
    const key = this.optionValue();
    if (!key || option === null || typeof option !== 'object') {
      return option;
    }
    return (option as Record<string, unknown>)[key];
  }

  protected resolveOptionLabel(option: unknown): string {
    const key = this.optionLabel();
    if (!key || option === null || typeof option !== 'object') {
      return stringifyLabel(option);
    }
    return stringifyLabel((option as Record<string, unknown>)[key]);
  }

  protected trackOption(index: number, option: unknown): unknown {
    const value = this.resolveOptionValue(option);
    return value !== undefined && value !== null ? value : index;
  }

  protected isOptionSelected(option: unknown): boolean {
    const optionValue = this.resolveOptionValue(option);
    const current = this.value();
    if (this.multiple()) {
      const values = Array.isArray(current) ? current : [];
      return values.some((selected) => this.compareWith()(optionValue, selected));
    }
    return this.compareWith()(optionValue, current);
  }

  protected itemContext(option: unknown): WiListboxItemContext {
    const value = this.resolveOptionValue(option);
    return {
      $implicit: option,
      option,
      value,
      selected: this.isOptionSelected(option),
    };
  }

  private markTouched(): void {
    this.onTouched();
    this.touch.emit();
  }
}

function stringifyLabel(value: unknown): string {
  if (value === null || value === undefined) {
    return '';
  }
  if (typeof value === 'string') {
    return value;
  }
  if (typeof value === 'number' || typeof value === 'boolean' || typeof value === 'bigint') {
    return String(value);
  }
  return '';
}

import { InputModalityDetector } from '@angular/cdk/a11y';
import type { NumberInput } from '@angular/cdk/coercion';
import {
  CdkMenu,
  CdkMenuGroup,
  CdkMenuItem,
  CdkMenuItemRadio,
  CdkMenuItemSelectable,
  CdkMenuTrigger,
} from '@angular/cdk/menu';
import {
  booleanAttribute,
  computed,
  Directive,
  effect,
  ElementRef,
  forwardRef,
  HOST_TAG_NAME,
  inject,
  input,
  numberAttribute,
  signal,
} from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import {
  createMenuPosition,
  deriveMenuSideFromTransformOrigin,
  MENU_SIDE,
  type MenuAlign,
  type MenuSide,
} from '@spartan-ng/brain/core';

import type { WiMenuAlign, WiMenuItemVariant, WiMenuSide } from './wi-menu.types';

const MENU_CONTENT_CLASSES = [
  'wi-menu',
  'z-50',
  'min-w-fit',
  'w-auto',
  'max-w-[min(100vw-2rem,20rem)]',
  'overflow-x-hidden',
  'overflow-y-auto',
  'rounded-control',
  'border',
  'border-outline-variant',
  'bg-surface',
  'p-2',
  'text-sm',
  'text-on-surface',
  'shadow-md',
  'outline-none',
  'my-[--spacing(var(--side-offset))]',
  'data-[state=open]:animate-in',
  'data-[state=closed]:animate-out',
  'data-[state=closed]:fade-out-0',
  'data-[state=open]:fade-in-0',
  'data-[state=closed]:zoom-out-95',
  'data-[state=open]:zoom-in-95',
  'data-[side=bottom]:slide-in-from-top-2',
  'data-[side=left]:slide-in-from-right-2',
  'data-[side=right]:slide-in-from-left-2',
  'data-[side=top]:slide-in-from-bottom-2',
].join(' ');

const MENU_ITEM_BASE_CLASSES = [
  'wi-menu__item',
  'relative',
  'flex',
  'w-full',
  'cursor-default',
  'items-center',
  'gap-2',
  'rounded-control-sm',
  'px-3',
  'py-2',
  'text-sm',
  'outline-hidden',
  'select-none',
  'transition-colors',
  'hover:bg-surface-variant',
  'focus:bg-surface-variant',
  'data-disabled:pointer-events-none',
  'data-disabled:opacity-50',
].join(' ');

const MENU_ITEM_VARIANT_CLASSES: Record<WiMenuItemVariant, string> = {
  default: 'text-on-surface',
  danger:
    'text-error hover:bg-error-container hover:text-on-error-container focus:bg-error-container focus:text-on-error-container',
};

const MENU_RADIO_CLASSES = [
  MENU_ITEM_BASE_CLASSES,
  'wi-menu__radio',
  'text-on-surface',
  'data-checked:bg-surface-variant',
].join(' ');

const MENU_LABEL_CLASSES = [
  'wi-menu__label',
  'block',
  'px-3',
  'py-1.5',
  'text-xs',
  'font-medium',
  'text-on-surface-variant',
].join(' ');

const MENU_SEPARATOR_CLASSES = [
  'wi-menu__separator',
  'my-1',
  '-mx-1',
  'h-px',
  'bg-outline-variant',
].join(' ');

/**
 * Mueve el foco DOM al ítem bajo el puntero (comportamiento tipo Radix/shadcn).
 * CDK solo mueve el foco con teclado; sin esto puede haber doble highlight.
 */
@Directive({
  selector: '[wiMenuFocusOnHover]',
  host: {
    '(mouseenter)': 'focusOnHover()',
  },
})
export class WiMenuFocusOnHoverDirective {
  private readonly menuItem = inject(CdkMenuItem, { self: true });
  private readonly parentMenu = inject(CdkMenu, { optional: true });
  private readonly inputModality = inject(InputModalityDetector);

  protected focusOnHover(): void {
    if (this.inputModality.mostRecentModality === 'touch' || this.menuItem.disabled) {
      return;
    }
    this.parentMenu?.setActiveMenuItem(this.menuItem);
  }
}

/**
 * Abre un menú popup a partir de un `ng-template`.
 *
 * Preferible en un `<button>` nativo (o `wi-button`) con nombre accesible.
 *
 * @example
 * ```html
 * <button type="button" [wiMenuTrigger]="menu" aria-label="Acciones">Abrir</button>
 * <ng-template #menu>
 *   <wi-menu>...</wi-menu>
 * </ng-template>
 * ```
 */
@Directive({
  selector: 'button[wiMenuTrigger], [wiMenuTrigger]',
  exportAs: 'wiMenuTrigger',
  providers: [{ provide: MENU_SIDE, useExisting: forwardRef(() => WiMenuTriggerDirective) }],
  hostDirectives: [
    {
      directive: CdkMenuTrigger,
      inputs: ['cdkMenuTriggerFor: wiMenuTrigger', 'cdkMenuTriggerData: wiMenuTriggerData'],
      outputs: ['cdkMenuOpened: opened', 'cdkMenuClosed: closed'],
    },
  ],
  host: {
    class: 'wi-menu-trigger',
    'data-slot': 'menu-trigger',
  },
})
export class WiMenuTriggerDirective {
  private readonly cdkTrigger = inject(CdkMenuTrigger, { host: true });

  /** Alineación horizontal/vertical relativa al trigger. */
  readonly align = input<WiMenuAlign>('start');
  /** Lado preferido del panel. */
  readonly side = input<WiMenuSide>('bottom');

  private readonly menuPosition = computed(() =>
    createMenuPosition(this.align() as MenuAlign, this.side() as MenuSide),
  );

  constructor() {
    const trigger = this.cdkTrigger as CdkMenuTrigger & {
      transformOriginSelector?: string;
    };
    trigger.transformOriginSelector = '[data-slot="menu"]';

    effect(() => {
      this.cdkTrigger.menuPosition = this.menuPosition();
    });
  }
}

/**
 * Panel del menú popup (`wi-menu`). Contiene label, ítems, radios y separadores.
 *
 * CDK Menu gestiona teclado, foco y cierre; la API pública no expone tipos Spartan/CDK.
 */
@Directive({
  selector: 'wi-menu, [wiMenu]',
  hostDirectives: [CdkMenu],
  host: {
    '[class]': 'hostClasses',
    'data-slot': 'menu',
    '[attr.data-state]': 'state()',
    '[attr.data-side]': 'resolvedSide()',
    '[style.--side-offset]': 'sideOffset()',
  },
})
export class WiMenuComponent {
  private readonly host = inject(CdkMenu);
  private readonly elementRef = inject(ElementRef<HTMLElement>);
  private readonly menuSide = inject(MENU_SIDE, { optional: true });

  protected readonly hostClasses = MENU_CONTENT_CLASSES;
  protected readonly state = signal<'open' | 'closed'>('open');
  protected readonly resolvedSide = signal<WiMenuSide>(
    (this.menuSide?.side() as WiMenuSide | undefined) ?? 'bottom',
  );

  /** Separación en unidades de spacing respecto al trigger. */
  readonly sideOffset = input<number, NumberInput>(1, { transform: numberAttribute });

  constructor() {
    const preferred = (this.menuSide?.side() as WiMenuSide | undefined) ?? 'bottom';
    setTimeout(() => {
      this.resolvedSide.set(
        deriveMenuSideFromTransformOrigin(
          this.elementRef.nativeElement.style.transformOrigin,
          preferred as MenuSide,
        ) as WiMenuSide,
      );
    });

    this.host.closed.pipe(takeUntilDestroyed()).subscribe(() => this.state.set('closed'));
  }
}

/** Agrupa ítems (p. ej. radios de selección única). */
@Directive({
  selector: 'wi-menu-group, [wiMenuGroup]',
  hostDirectives: [CdkMenuGroup],
  host: {
    class: 'wi-menu__group block',
    'data-slot': 'menu-group',
  },
})
export class WiMenuGroupComponent {}

/** Etiqueta no interactiva (cabecera de sección). */
@Directive({
  selector: 'wi-menu-label, [wiMenuLabel]',
  host: {
    '[class]': 'hostClasses',
    'data-slot': 'menu-label',
  },
})
export class WiMenuLabelComponent {
  protected readonly hostClasses = MENU_LABEL_CLASSES;
}

/** Separador visual entre grupos. */
@Directive({
  selector: 'wi-menu-separator, [wiMenuSeparator]',
  host: {
    '[class]': 'hostClasses',
    'data-slot': 'menu-separator',
    role: 'separator',
    'aria-orientation': 'horizontal',
  },
})
export class WiMenuSeparatorComponent {
  protected readonly hostClasses = MENU_SEPARATOR_CLASSES;
}

/**
 * Ítem de acción del menú. Usar en `<button>`.
 *
 * @example
 * ```html
 * <button type="button" wiMenuItem (triggered)="onEdit()">Editar</button>
 * ```
 */
@Directive({
  selector: 'button[wiMenuItem], [wiMenuItem]',
  hostDirectives: [
    {
      directive: CdkMenuItem,
      inputs: ['cdkMenuItemDisabled: disabled'],
      outputs: ['cdkMenuItemTriggered: triggered'],
    },
    WiMenuFocusOnHoverDirective,
  ],
  host: {
    '[class]': 'classes()',
    'data-slot': 'menu-item',
    '[attr.disabled]': 'isButton && disabled() ? "" : null',
    '[attr.data-disabled]': 'disabled() ? "" : null',
    '[attr.data-variant]': 'variant()',
  },
})
export class WiMenuItemDirective {
  protected readonly isButton = inject(HOST_TAG_NAME) === 'button';

  readonly disabled = input(false, { transform: booleanAttribute });
  readonly variant = input<WiMenuItemVariant>('default');

  protected readonly classes = computed(() =>
    [MENU_ITEM_BASE_CLASSES, MENU_ITEM_VARIANT_CLASSES[this.variant()]].join(' '),
  );
}

/** @internal Bridge CDK radio con `keepOpen` configurable. */
@Directive({
  selector: '[wiMenuRadioCdk]',
  providers: [
    { provide: CdkMenuItemRadio, useExisting: WiMenuRadioCdkDirective },
    { provide: CdkMenuItemSelectable, useExisting: WiMenuRadioCdkDirective },
    { provide: CdkMenuItem, useExisting: CdkMenuItemSelectable },
  ],
})
export class WiMenuRadioCdkDirective extends CdkMenuItemRadio {
  readonly keepOpen = input(false, { transform: booleanAttribute });

  override trigger(options?: { keepOpen: boolean }): void {
    super.trigger({ ...options, keepOpen: this.keepOpen() });
  }
}

/**
 * Ítem radio (selección única dentro del menú / grupo).
 * Ideal para filtros donde el trigger refleja la opción activa.
 *
 * @example
 * ```html
 * <button
 *   type="button"
 *   wiMenuRadio
 *   [checked]="selected() === 'adhoc'"
 *   (triggered)="selected.set('adhoc')"
 * >
 *   Adhoc
 * </button>
 * ```
 */
@Directive({
  selector: 'button[wiMenuRadio], [wiMenuRadio]',
  hostDirectives: [
    {
      directive: WiMenuRadioCdkDirective,
      inputs: ['cdkMenuItemDisabled: disabled', 'cdkMenuItemChecked: checked', 'keepOpen'],
      outputs: ['cdkMenuItemTriggered: triggered'],
    },
    WiMenuFocusOnHoverDirective,
  ],
  host: {
    '[class]': 'hostClasses',
    'data-slot': 'menu-radio',
    '[attr.data-disabled]': 'cdkItem.disabled ? "" : null',
    '[attr.data-checked]': 'cdkItem.checked ? "" : null',
  },
})
export class WiMenuRadioDirective {
  protected readonly hostClasses = MENU_RADIO_CLASSES;
  protected readonly cdkItem = inject(WiMenuRadioCdkDirective);
}

import { InputModalityDetector } from '@angular/cdk/a11y';
import type { NumberInput } from '@angular/cdk/coercion';
import {
  CdkMenu,
  CdkMenuGroup,
  CdkMenuItem,
  CdkMenuItemRadio,
  CdkMenuItemSelectable,
  CdkMenuTrigger,
} from '@angular/cdk/menu';
import {
  booleanAttribute,
  computed,
  Directive,
  effect,
  ElementRef,
  forwardRef,
  HOST_TAG_NAME,
  inject,
  input,
  numberAttribute,
  signal,
} from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import {
  createMenuPosition,
  deriveMenuSideFromTransformOrigin,
  MENU_SIDE,
  type MenuAlign,
  type MenuSide,
} from '@spartan-ng/brain/core';

import type { WiMenuAlign, WiMenuItemVariant, WiMenuSide } from './wi-menu.types';

const MENU_CONTENT_CLASSES = [
  'wi-menu',
  'z-50',
  'min-w-fit',
  'w-auto',
  'max-w-[min(100vw-2rem,20rem)]',
  'overflow-x-hidden',
