import {
  booleanAttribute,
  Component,
  computed,
  Directive,
  effect,
  inject,
  input,
  model,
  TemplateRef,
  untracked,
} from '@angular/core';
import {
  BrnDialog,
  BrnDialogClose,
  BrnDialogDescription,
  BrnDialogOverlay,
  BrnDialogRef,
  BrnDialogTitle,
  provideBrnDialogDefaultOptions,
} from '@spartan-ng/brain/dialog';
import { WiButtonComponent } from '@wiloc/ui/button';
import { WiIconComponent } from '@wiloc/ui/icon';

import { WI_DIALOG_SIZE } from './wi-dialog.tokens';
import type { WiDialogSize, WiDialogState } from './wi-dialog.types';
import { injectWiOverlaysI18n } from '../wi-overlays.i18n';

const OVERLAY_CLASSES = [
  'wi-dialog__overlay',
  'bg-on-background/50',
  'data-[state=open]:animate-in',
  'data-[state=closed]:animate-out',
  'data-[state=closed]:fade-out-0',
  'data-[state=open]:fade-in-0',
].join(' ');

/** Pane CDK: ancho concreto (sin `w-full`) para que el position strategy centre bien. */
const PANEL_BASE_CLASSES = 'wi-dialog__pane';

const CONTENT_BASE_CLASSES = [
  'wi-dialog__content',
  'relative',
  'grid',
  'w-full',
  'gap-4',
  'rounded-control-lg',
  'border',
  'border-outline-variant',
  'bg-surface',
  'p-6',
  'text-sm',
  'text-on-surface',
  'shadow-lg',
