              }
              @for (column of displayColumns(); track column.id) {
                <th class="wi-table__filter-cell px-2 py-1.5 font-normal">
                  @if (column.filterable) {
                    <div class="flex min-w-[8rem] items-center gap-1">
                      @if (column.filterType === 'select') {
